def ac(*items):
    return [{"id": f"AC-{i+1}", "given": g, "when": w, "then": t} for i, (g, w, t) in enumerate(items)]


def ui(id_, kind, title, statement, traces, forma=(), folio=(), gaps=(), actors=(), states=(), actions=(), phone="", acs=(), detail=None):
    return dict(id=id_, kind=kind, title=title, statement=statement, traces=list(traces), forma_components=list(forma),
                folio_elements=list(folio), capability_gaps=list(gaps), actors=list(actors), states=list(states),
                actions=list(actions), responsive=phone, acceptance_criteria=acs, detail=detail or {}, status="proposed",
                origin="ui-refinement 2026-11-23 (owner instruction: make designs more concrete)")


